module binomial_solver(\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] X,\n    output reg [6:0] n,\n    output reg [3:0] k,\n    output reg done\n);\n\n    // Parameters\n    parameter DATA_WIDTH = 16;\n    parameter N_WIDTH = 7;\n    parameter K_WIDTH = 4;\n    parameter ADDR_WIDTH = 9;\n    parameter NUM_ENTRIES = 300;\n\n    // State declarations\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] SEARCH  = 2'd1;\n    localparam [1:0] DONE_ST = 2'd2;\n\n    // Internal regs\n    reg [1:0] state;\n    reg [8:0] addr;\n    reg [6:0] n_reg;\n    reg [3:0] k_reg;\n    reg done_reg;\n\n    // ROM declarations\n    reg [6:0] rom_n [0:299];\n    reg [3:0] rom_k [0:299];\n    reg [15:0] rom_coeff [0:299];\n\n    // ROM Initialization (partial example)\n    integer i;\n    initial begin\n        // Example values - should be replaced with actual precomputed binomial coefficients\n        // Entry 0\n        rom_n[0] = 7'd0;\n        rom_k[0] = 4'd0;\n        rom_coeff[0] = 16'd1;\n        // Entry 1\n        rom_n[1] = 7'd1;\n        rom_k[1] = 4'd0;\n        rom_coeff[1] = 16'd1;\n        // ... (remaining entries initialized similarly)\n        // Defaults for remaining entries\n        for (i = 2; i < NUM_ENTRIES; i = i + 1) begin\n            rom_n[i] = 7'd0;\n            rom_k[i] = 4'd0;\n            rom_coeff[i] = 16'd0;\n        end\n    end\n\n    // FSM Logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            addr <= 9'd0;\n            n_reg <= 7'd0;\n            k_reg <= 4'd0;\n            done_reg <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done_reg <= 1'b0;\n                    if (start) begin\n                        state <= SEARCH;\n                        addr <= 9'd0;\n                    end\n                end\n                \n                SEARCH: begin\n                    if (rom_coeff[addr] == X) begin\n                        n_reg <= rom_n[addr];\n                        k_reg <= rom_k[addr];\n                        state <= DONE_ST;\n                    end else if (addr == (NUM_ENTRIES - 1)) begin\n                        // No match found\n                        n_reg <= 7'd0;\n                        k_reg <= 4'd0;\n                        state <= DONE_ST;\n                    end else begin\n                        addr <= addr + 9'd1;\n                    end\n                end\n                \n                DONE_ST: begin\n                    done_reg <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n    \n    // Output assignments\n    assign n = n_reg;\n    assign k = k_reg;\n    assign done = done_reg;\n\nendmodule